CREATE FUNCTION "yunipals_ownership_4e77f52b_v4".source_boundary(selected_collection text)
      RETURNS TABLE(source_id text,collection text,chain_id integer,contract_address text,
        block_number bigint,block_hash text,block_timestamp bigint,observed_at timestamptz,
        heartbeat_at bigint,ready boolean,release_id text,manifest_hash text,policy text)
      LANGUAGE plpgsql STABLE SECURITY INVOKER ROWS 1 SET search_path=pg_catalog AS $yunipals_ownership_0$
      DECLARE config jsonb; v_definition jsonb; observation record; runtime jsonb;
        checkpoint text; indexed bigint; verified bigint; required bigint; available bigint;
        boundary jsonb; clock_ms bigint; source_record record; stored_release record;
      BEGIN
        SELECT value INTO config FROM jsonb_array_elements('[{"collection":"base","sourceId":"ownership:base","policy":{"kind":"latest"},"source":{"id":"ownership:base","feature":"ownership","chainId":8453,"contractName":"YunipalsBase","address":"0x98433df878e8c898cb907345c3a7756e5f72240f","startBlock":"22224075","endBlock":null,"enabled":true,"abiHash":"0x4fd7fc34d0a288da0680ded8e7c941bd66b2020563493f389e47da1617154545","events":["RoleGranted","RoleRevoked","Transfer"],"receiptRequirement":"full","policies":[{"kind":"latest"},{"kind":"finalized"}],"receiptStartBlock":"22224075"}},{"collection":"base-islands-v2","sourceId":"islands:base:v2","policy":{"kind":"latest"},"source":{"id":"islands:base:v2","feature":"islands","chainId":8453,"contractName":"YunipalsBaseIslandsV2","address":"0x79b68a12a2952a9a8d0cc4d0b3fb00252c41d168","startBlock":"52587956","endBlock":null,"enabled":true,"abiHash":"0x58c22e8a90029c0e7f4ab34e087c186992c654895c8ffd660223e454bd8515ee","events":["AirdropFinalized","OwnershipTransferred","Transfer"],"receiptRequirement":"none","policies":[{"kind":"latest"},{"kind":"finalized"},{"kind":"depth","subsequentBlocks":3}]}},{"collection":"bnb","sourceId":"ownership:bnb","policy":{"kind":"depth","subsequentBlocks":20},"source":{"id":"ownership:bnb","feature":"ownership","chainId":56,"contractName":"YunipalsBnb","address":"0x85f0e02cb992aa1f9f47112f815f519ef1a59e2d","startBlock":"7579197","endBlock":null,"enabled":true,"abiHash":"0x4fd7fc34d0a288da0680ded8e7c941bd66b2020563493f389e47da1617154545","events":["RoleGranted","RoleRevoked","Transfer"],"receiptRequirement":"full","policies":[{"kind":"latest"},{"kind":"finalized"},{"kind":"depth","subsequentBlocks":20}],"receiptStartBlock":"122080975"}},{"collection":"ethereum","sourceId":"ownership:ethereum","policy":{"kind":"latest"},"source":{"id":"ownership:ethereum","feature":"ownership","chainId":1,"contractName":"YunipalsEthereum","address":"0x85f0e02cb992aa1f9f47112f815f519ef1a59e2d","startBlock":"12134519","endBlock":null,"enabled":true,"abiHash":"0x4fd7fc34d0a288da0680ded8e7c941bd66b2020563493f389e47da1617154545","events":["RoleGranted","RoleRevoked","Transfer"],"receiptRequirement":"full","policies":[{"kind":"latest"},{"kind":"finalized"}],"receiptStartBlock":"19442152"}},{"collection":"ethereum-islands","sourceId":"islands:ethereum","policy":{"kind":"latest"},"source":{"id":"islands:ethereum","feature":"islands","chainId":1,"contractName":"YunipalsIslands","address":"0xa22e2f53ca787414dc0643c399f92234949e2305","startBlock":"14570451","endBlock":null,"enabled":true,"abiHash":"0xaa77af20a85176a77f383173594ca6af93f3c43a79a0f1c4a76cb291516bc9f7","events":["OwnershipTransferred","Transfer"],"receiptRequirement":"none","policies":[{"kind":"latest"},{"kind":"finalized"}]}},{"collection":"polygon","sourceId":"ownership:polygon","policy":{"kind":"latest"},"source":{"id":"ownership:polygon","feature":"ownership","chainId":137,"contractName":"YunipalsPolygon","address":"0x85f0e02cb992aa1f9f47112f815f519ef1a59e2d","startBlock":"21814218","endBlock":null,"enabled":true,"abiHash":"0x4fd7fc34d0a288da0680ded8e7c941bd66b2020563493f389e47da1617154545","events":["RoleGranted","RoleRevoked","Transfer"],"receiptRequirement":"full","policies":[{"kind":"latest"},{"kind":"finalized"}],"receiptStartBlock":"54889689"}}]'::jsonb)
          WHERE value->>'collection'=selected_collection;
        IF config IS NULL THEN RAISE EXCEPTION 'source_unknown'; END IF;
        v_definition:=config->'source';
        SELECT r.physical_schema,r.build_id,r.manifest_hash INTO stored_release
          FROM yunipals_indexer_control.release r WHERE r.id='0x4e77f52be3e0daa7075a22afe03fbeb7352daee788265ff69fe5c9ec2cf5c1f3';
        IF NOT FOUND OR stored_release.physical_schema<>'unified_ypal_20261023_v1' OR
          stored_release.build_id<>'71e2a7f3b7' OR stored_release.manifest_hash<>'0x23d5ca6870ce9828d435b9bf5be2291c775c23703e9ab77047f2970198e9c112'
          THEN RAISE EXCEPTION 'release_mismatch'; END IF;
        SELECT s.chain_id,s.manifest_hash,s.definition::jsonb AS definition INTO source_record
          FROM "unified_ypal_20261023_v1".indexer_source s WHERE s.id=v_definition->>'id';
        IF NOT FOUND OR source_record.chain_id<>(v_definition->>'chainId')::integer
          OR source_record.manifest_hash<>'0x23d5ca6870ce9828d435b9bf5be2291c775c23703e9ab77047f2970198e9c112' OR source_record.definition<>v_definition
          THEN RAISE EXCEPTION 'source_mismatch'; END IF;
        SELECT m.value INTO runtime FROM "unified_ypal_20261023_v1"._ponder_meta m WHERE m.key='app';
        IF runtime IS NULL OR runtime->>'version' IS DISTINCT FROM '6' OR runtime->>'build_id' IS DISTINCT FROM '71e2a7f3b7'
          OR runtime->>'is_dev' IS DISTINCT FROM '0' OR runtime->>'is_locked' IS DISTINCT FROM '1'
          OR COALESCE(runtime->>'heartbeat_at','')!~'^[0-9]{1,16}$' THEN RAISE EXCEPTION 'runtime_unavailable'; END IF;
        clock_ms:=floor(extract(epoch FROM statement_timestamp())*1000)::bigint;
        IF (runtime->>'heartbeat_at')::bigint>clock_ms OR clock_ms-(runtime->>'heartbeat_at')::bigint>180000
          THEN RAISE EXCEPTION 'observation_stale'; END IF;
        SELECT s.* INTO observation FROM yunipals_indexer_control.chain_status s
          WHERE s.release_id='0x4e77f52be3e0daa7075a22afe03fbeb7352daee788265ff69fe5c9ec2cf5c1f3' AND s.chain_id=(v_definition->>'chainId')::integer;
        IF NOT FOUND OR observation.halted OR observation.error_code IS NOT NULL
          OR observation.head_number IS NULL OR observation.observed_at_ms IS NULL
          OR observation.head_hash IS NULL OR observation.head_hash!~'^0x[0-9a-f]{64}$'
          OR observation.observed_at_ms>clock_ms OR clock_ms-observation.observed_at_ms>180000
          THEN RAISE EXCEPTION 'source_unavailable'; END IF;
        IF NOT EXISTS(SELECT 1 FROM "unified_ypal_20261023_v1".chain_block b WHERE b.chain_id=observation.chain_id
          AND b.block_number=observation.witness_number AND b.block_hash=observation.witness_hash)
          THEN RAISE EXCEPTION 'indexer_witness_unverified'; END IF;
        SELECT c.latest_checkpoint INTO checkpoint FROM "unified_ypal_20261023_v1"._ponder_checkpoint c
          WHERE c.chain_id=observation.chain_id;
        IF checkpoint IS NULL OR checkpoint!~'^[0-9]{75}$' OR checkpoint=repeat('0',75)
          OR substring(checkpoint FROM 11 FOR 16)::bigint<>observation.chain_id
          THEN RAISE EXCEPTION 'checkpoint_unavailable'; END IF;
        indexed:=substring(checkpoint FROM 27 FOR 16)::bigint
          -CASE WHEN substring(checkpoint FROM 43)=repeat('9',33) THEN 0 ELSE 1 END;
        IF EXISTS(SELECT 1 FROM jsonb_each(observation.anchors)
          WHERE COALESCE(value->>'number','')!~'^(0|[1-9][0-9]*)$'
            OR COALESCE(value->>'hash','')!~'^0x[0-9a-f]{64}$') THEN RAISE EXCEPTION 'anchor_invalid'; END IF;
        SELECT max((value->>'number')::bigint) INTO verified FROM jsonb_each(observation.anchors);
        indexed:=least(indexed,verified);
        IF verified IS NULL OR indexed>observation.head_number THEN RAISE EXCEPTION 'observation_inconsistent'; END IF;
        required:=observation.head_number;
        IF config->'policy'->>'kind'='depth' THEN
          required:=required-(config->'policy'->>'subsequentBlocks')::bigint;
        ELSIF config->'policy'->>'kind'='finalized' THEN
          IF observation.finality_error_code IS NOT NULL OR observation.finalized_number IS NULL
            THEN RAISE EXCEPTION 'finality_unavailable'; END IF;
          IF observation.finalized_number>observation.head_number OR observation.finalized_hash IS NULL
            OR (observation.finalized_number=observation.head_number AND observation.finalized_hash<>observation.head_hash)
            THEN RAISE EXCEPTION 'observation_inconsistent'; END IF;
          required:=observation.finalized_number;
        END IF;
        IF v_definition->>'endBlock' IS NOT NULL THEN required:=least(required,(v_definition->>'endBlock')::bigint); END IF;
        available:=least(indexed,verified,required);
        IF available<(v_definition->>'startBlock')::bigint THEN RAISE EXCEPTION 'not_indexed'; END IF;
        boundary:=observation.anchors->available::text;
        IF boundary IS NULL OR COALESCE(boundary->>'hash','')!~'^0x[0-9a-f]{64}$'
          OR COALESCE(boundary->>'timestamp','')!~'^(0|[1-9][0-9]*)$'
          THEN RAISE EXCEPTION 'anchor_unavailable'; END IF;
        RETURN QUERY SELECT v_definition->>'id',selected_collection,observation.chain_id,v_definition->>'address',
          available,boundary->>'hash',(boundary->>'timestamp')::bigint,
          to_timestamp(observation.observed_at_ms::numeric/1000),
          (runtime->>'heartbeat_at')::bigint,available>=required,'0x4e77f52be3e0daa7075a22afe03fbeb7352daee788265ff69fe5c9ec2cf5c1f3','0x23d5ca6870ce9828d435b9bf5be2291c775c23703e9ab77047f2970198e9c112',
          CASE WHEN config->'policy'->>'kind'='depth' THEN 'depth:'||(config->'policy'->>'subsequentBlocks')
            ELSE config->'policy'->>'kind' END;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE='YI001',MESSAGE='unified_ownership_source_unavailable',DETAIL=SQLERRM;
      END $yunipals_ownership_0$

CREATE FUNCTION "yunipals_ownership_4e77f52b_v4".source_probe(selected_collection text) RETURNS jsonb
      LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $probe$
      DECLARE boundary record; reason text;
      BEGIN
        SELECT * INTO boundary FROM "yunipals_ownership_4e77f52b_v4".source_boundary(selected_collection);
        RETURN to_jsonb(boundary)||jsonb_build_object('block_number',boundary.block_number::text,
          'block_timestamp',boundary.block_timestamp::text,'heartbeat_at',boundary.heartbeat_at::text,
          'available',true,'reason',CASE WHEN boundary.ready THEN 'ready' ELSE 'catching_up' END);
      EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS reason=PG_EXCEPTION_DETAIL;
        RETURN jsonb_build_object('collection',selected_collection,'available',false,'ready',false,
          'reason',CASE WHEN reason~'^[a-z_]{1,80}$' THEN reason ELSE 'source_unavailable' END);
      END $probe$

CREATE FUNCTION "yunipals_ownership_4e77f52b_v4".base_metadata_frame(require_approval boolean DEFAULT true)
    RETURNS TABLE(block_number bigint,block_hash text,frontier text,frontier_event_id text,frontier_event_hash text)
    LANGUAGE plpgsql STABLE SECURITY INVOKER ROWS 1 SET search_path=pg_catalog AS $yunipals_native_base$
    DECLARE boundary record; latest record; approval record;
    BEGIN
      SELECT * INTO boundary FROM "yunipals_ownership_4e77f52b_v4".source_boundary('base');
      IF NOT FOUND OR boundary.policy<>'latest' THEN RAISE EXCEPTION 'base_policy_unavailable'; END IF;
      IF NOT EXISTS(SELECT 1 FROM "unified_ypal_20261023_v1".indexer_source s WHERE s.id='metadata:base' AND s.chain_id=8453
        AND s.manifest_hash='0x23d5ca6870ce9828d435b9bf5be2291c775c23703e9ab77047f2970198e9c112' AND s.definition::jsonb='{"id":"metadata:base","feature":"base-metadata","chainId":8453,"contractName":"YunipalsBaseMetadata","address":"0x98433df878e8c898cb907345c3a7756e5f72240f","startBlock":"22224075","endBlock":null,"enabled":true,"abiHash":"0x10ed1bdc491b581039c80bfe1a53832615bda607560c998ad5202542cf9a4259","events":["Mint","Update"],"receiptRequirement":"none","policies":[{"kind":"latest"},{"kind":"finalized"}]}'::jsonb)
        THEN RAISE EXCEPTION 'base_metadata_source_mismatch'; END IF;
      SELECT e.id,e.block_hash INTO latest FROM "unified_ypal_20261023_v1".canonical_event e
        WHERE e.source_id='metadata:base' AND e.chain_id=8453 AND e.address='0x98433df878e8c898cb907345c3a7756e5f72240f'
          AND e.abi_hash='0x10ed1bdc491b581039c80bfe1a53832615bda607560c998ad5202542cf9a4259' AND e.block_number>=22224075::bigint
          AND e.block_number<=boundary.block_number
        ORDER BY e.block_number DESC,e.transaction_index DESC,e.log_index DESC LIMIT 1;
      block_number:=boundary.block_number;block_hash:=boundary.block_hash;
      frontier_event_id:=latest.id;frontier_event_hash:=latest.block_hash;
      frontier:=COALESCE(latest.id||':'||latest.block_hash,'none');
      IF require_approval THEN
        SELECT a.* INTO approval FROM metadata_source.native_base_metadata_state a
          JOIN metadata_source.chain_metadata_scan s ON s.name='base_metadata_v1' AND s.ingestion_mode='native'
          WHERE a.release_id='0x4e77f52be3e0daa7075a22afe03fbeb7352daee788265ff69fe5c9ec2cf5c1f3';
        IF NOT FOUND OR approval.read_identity IS DISTINCT FROM '0xcac869bf65116323b9e1e8e539d999964ad740ab1e4194be0a335ce624c5ea67' OR approval.state<>'ready'
          OR approval.frontier IS DISTINCT FROM frontier OR approval.implementation IS DISTINCT FROM '0x4ad380760abb9fad95cd48ef2d7c46ed5a072fca'
          OR approval.checked_at<statement_timestamp()-interval '90 seconds' OR approval.checked_at>statement_timestamp()
          OR approval.checked_block>boundary.block_number OR NOT EXISTS(SELECT 1 FROM "unified_ypal_20261023_v1".chain_block b
            WHERE b.chain_id=8453 AND b.block_number=approval.checked_block AND b.block_hash=approval.checked_hash)
          THEN RAISE EXCEPTION 'base_metadata_approval_pending'; END IF;
      END IF;
      RETURN NEXT;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION USING ERRCODE='YI001',MESSAGE='Native Base metadata unavailable',DETAIL=SQLERRM;
    END $yunipals_native_base$
